const body = $input.first().json.body || $input.first().json;

const adType     = (body.ad_type     || '').toLowerCase().trim();
const entityUuid = (body.entity_uuid || '').trim();
const leadName   = (body.lead_name   || 'Valued Customer').trim();
const phone      = (body.phone       || '').replace(/\s+/g, '').trim();
const country    = (body.country     || 'SA').toUpperCase().trim();
const email      = (body.email       || '').trim();

if (!['listing', 'project'].includes(adType))
  throw new Error('ad_type must be listing or project. Got: ' + adType);
if (!entityUuid)
  throw new Error('entity_uuid is required');
if (!phone)
  throw new Error('phone is required');

const tzMap = {
  SA: 'Asia/Riyadh',   AE: 'Asia/Dubai',    KW: 'Asia/Kuwait',
  BH: 'Asia/Bahrain',  QA: 'Asia/Qatar',    OM: 'Asia/Muscat',
  EG: 'Africa/Cairo',  JO: 'Asia/Amman',    LB: 'Asia/Beirut',
  IQ: 'Asia/Baghdad',  YE: 'Asia/Aden',     PK: 'Asia/Karachi',
  IN: 'Asia/Kolkata',  DEFAULT: 'Asia/Riyadh'
};
const timezone = tzMap[country] || tzMap.DEFAULT;

const now = new Date();
const localHour = parseInt(
  now.toLocaleString('en-US', { hour: 'numeric', hour12: false, timeZone: timezone })
);
// First-submission leads are always called immediately.
// Calling hours restriction only applies to retry attempts.
const retryCountRaw = parseInt(body.retry_count || '0');
const isCallableNow = retryCountRaw === 0 || (localHour >= 9 && localHour < 21);

const escapeSql = (str) => {
  if (typeof str !== 'string') return '';
  return str.replace(/'/g, "''");
};

return [{
  json: {
    adType, entityUuid, leadName, phone, country, email,
    timezone, isCallableNow,
    receivedAt: now.toISOString(),
    retryCount: parseInt(body.retry_count || '0'),
    crmLeadId:  body.crm_lead_id || null,

    // SQL safe string values for direct interpolation
    sqlLeadName: escapeSql(leadName),
    sqlPhone: escapeSql(phone),
    sqlEmail: escapeSql(email),
    sqlCountry: escapeSql(country),
    sqlTimezone: escapeSql(timezone)
  }
}];

const data  = $input.first().json;
const retry = data.retryCount || 0;
const next  = new Date();
next.setDate(next.getDate() + (retry === 0 ? 0 : retry));
next.setHours(9, 0, 0, 0);
return [{
  json: {
    ...data,
    action:       'SCHEDULED_LATER',
    scheduledAt:  next.toISOString(),
    reason:       'Outside calling hours (9am-9pm ' + data.timezone + ')'
  }
}];

const project = $('Fetch Project Details').first().json;
const layoutItems = $('Fetch Project Layouts').all();

const layouts = layoutItems.map(item => item.json).filter(l => l.title || l.price);

const prices = layouts.map(l => Number(l.price)).filter(p => !isNaN(p) && p > 0);
const minPrice = prices.length > 0 ? Math.min(...prices) : null;
const maxPrice = prices.length > 0 ? Math.max(...prices) : null;

return [{
  json: {
    ...project,
    min_price: minPrice,
    max_price: maxPrice,
    layouts: layouts
  }
}];

const input   = $('Extract & Validate Input').first().json;
const adType  = input.adType;

let propertyContext = '';
let propertyName    = '';
let priceRange      = '';
let propertyCity    = '';

if (adType === 'listing') {
  const row = $('Fetch Listing Details').first().json;
  if (!row || !row.id)
    throw new Error('Listing not found or inactive: ' + input.entityUuid);

  propertyName = row.en_title || row.ar_title || 'the property';
  priceRange   = row.price
    ? 'SAR ' + Number(row.price).toLocaleString()
    : 'Price on request';
  propertyCity = row.city || '';

  propertyContext = [
    '=== PROPERTY DETAILS ===',
    'Type: Individual Listing',
    'Name: ' + propertyName,
    'Location: ' + [row.district, row.city].filter(Boolean).join(', '),
    'Price: ' + priceRange,
    'Area: ' + (row.area_sqm || 'N/A') + ' sqm',
    'Bedrooms: ' + (row.bedrooms  || 'N/A'),
    'Bathrooms: ' + (row.bathrooms || 'N/A'),
    'Completion: ' + (row.completion_status || 'N/A'),
    row.project_name_en ? 'Part of Project: ' + row.project_name_en : '',
    row.en_description  ? 'Details: ' + String(row.en_description).substring(0, 400) : '',
    '========================',
  ].filter(Boolean).join('\n');

} else {
  const row = $('Merge Project + Layouts').first().json;
  if (!row || !row.project_id)
    throw new Error('Project not found: ' + input.entityUuid);

  propertyName = row.name_en || row.name_ar || 'the project';
  propertyCity = row.city || '';

  const minP = row.min_price ? 'SAR ' + Number(row.min_price).toLocaleString() : 'N/A';
  const maxP = row.max_price ? 'SAR ' + Number(row.max_price).toLocaleString() : 'N/A';
  priceRange = (row.min_price || row.max_price) ? minP + ' – ' + maxP : 'Contact for pricing';

  let layouts = [];
  try {
    layouts = Array.isArray(row.layouts)
      ? row.layouts
      : JSON.parse(row.layouts || '[]');
  } catch(e) { layouts = []; }

  const layoutLines = layouts.length > 0
    ? layouts.slice(0, 8).map((l, i) => {
        const p = l.price ? 'SAR ' + Number(l.price).toLocaleString() : 'TBD';
        return `  ${i + 1}. ${l.title || 'Unit'}: ${l.bedrooms || 'N/A'} BR | ${l.area_sqm || 'N/A'} sqm | ${p} | ${l.completion_status || 'N/A'}`;
      }).join('\n')
    : '  No unit layout data available yet';

  propertyContext = [
    '=== PROJECT DETAILS ===',
    'Type: Compound / Development Project',
    'Name: ' + propertyName,
    'Location: ' + [row.district, row.city].filter(Boolean).join(', '),
    'Price Range: ' + priceRange,
    row.completion_status ? 'Completion Status: ' + row.completion_status : '',
    row.expected_delivery ? 'Expected Delivery: ' + row.expected_delivery : '',
    row.total_units ? 'Total Units: ' + row.total_units : '',
    row.description_en ? 'About: ' + String(row.description_en).substring(0, 400) : '',
    'Available Unit Types:',
    layoutLines,
    '========================',
  ].filter(Boolean).join('\n');
}

const systemPrompt = `You are Sara, a professional real estate consultant at Tamleeq.
You are making an outbound qualification call to ${input.leadName}, who recently submitted an inquiry about a property through one of our advertisements.

${propertyContext}

STRICT RULES:
1. You are calling ONLY about "${propertyName}". Do not discuss other properties.
2. If the lead asks about a different property, say: "I can have a specialist contact you about that. Today I am specifically calling about ${propertyName}."
3. Do not fabricate any prices, areas, or details not listed above.
4. Keep the call friendly, professional, and under 5 minutes.
5. If the lead says it is a bad time, say: "No problem at all. When would be a good time for us to call back?"
6. Speak naturally — this is a phone call, not a form. Do not read out lists robotically.
7. If the lead does not answer, do not leave information — the system will retry automatically.
8. BUDGET OBJECTIONS & VALUE SELLING (CRITICAL): If the lead says the price is very high or expensive, DO NOT immediately declare a budget mismatch. Follow this structured flow:
   - Step A: Acknowledge the price concern with tact (e.g., "I completely understand that it is a significant investment").
   - Step B: Sell the value — highlight the premium location, layout, amenities, or potential rental yield using ONLY the details listed in the property description above.
   - Step C: Mention payment flexibility — installment structures, bank financing, or down-payment options.
   - Step D: If still hesitant, offer the cheaper layouts in this project starting from the minimum price listed in the project details block above and ask for their target budget to find the right fit.

QUALIFICATION FLOW — cover these 3 gates naturally in conversation:
Step 1 — Confirm interest: "I am calling about ${propertyName}. Are you still interested in learning more?"
Step 2 — GATE 1 (Budget): Ask what budget range they have in mind. Apply value selling and objection handling as per Rule 8 above. Only declare budget mismatch if their stated budget is strictly below the minimum price listed in the project details block above AND they cannot stretch.
Step 3 — GATE 2 (City/Location): Ask if they are specifically looking to buy in ${propertyCity}. If they say they want a completely different city and cannot be flexible, this is a disqualifier.
Step 4 — GATE 3 (Delivery Preference): Mention the completion status and expected delivery from the project details above and ask if they are comfortable with that, or if they need something ready to move into immediately. If they need ready-to-move and this project is not, this is a disqualifier.
Step 5 — Purpose: "Is this for your personal home or as an investment?"
Step 6 — Timeline: "When are you ideally looking to make a purchase?"
Step 7 — Decision maker: "Are you the main decision maker, or will family members also be involved?"

OUTCOME CRITERIA:
- QUALIFIED: Budget is compatible (meets minimum price in project details), city is confirmed, delivery preference is accepted, timeline within 12 months. Also use QUALIFIED if they need to check with family — note it in the closing summary.
- NOT_INTERESTED: Lead explicitly says not interested or already purchased elsewhere, OR strongly rejects the city after no flexibility, OR strongly rejects the delivery timeline after no flexibility.
- NO_BUDGET_MATCH: Lead's stated budget is strictly below the lowest price in the project details block AND they cannot stretch even after value selling.
- CALLBACK_NEEDED: Lead is mid-call and cannot speak now (bad timing) — they need to be called back.

CLOSING AND OUTCOME PROTOCOL:
When the conversation is complete, you MUST end the call using one of the following exact closing phrases:
- For QUALIFIED: "I'm happy to confirm that you are qualified! One of our specialists will be in touch very soon. Have a great day. Goodbye!"
- For CALLBACK_NEEDED: "No problem at all. I will note down that a callback is needed. One of our specialists will be in touch very soon. Have a great day. Goodbye!"
- For NO_BUDGET_MATCH: "It seems there is no budget match for this property at the moment. One of our specialists will be in touch very soon. Have a great day. Goodbye!"
- For NOT_INTERESTED: "Understood, I will note that you are not interested. Thank you for your time. Have a great day. Goodbye!"

STRICT RULE: Do not output any other text after the closing phrase. The goodbye must be your last word so the call can hang up.`;

const escapeSql = (str) => {
  if (typeof str !== 'string') return '';
  return str.replace(/'/g, "''");
};

return [{
  json: {
    ...input,
    systemPrompt,
    propertyName,
    priceRange,
    propertyCity,
    adType,
    entityUuid: input.entityUuid,

    // Pre-escaped SQL variables
    sqlPropertyName: escapeSql(propertyName),
    sqlPropertyCity: escapeSql(propertyCity),
    sqlPriceRange: escapeSql(priceRange),
    sqlAdType: escapeSql(adType)
  }
}];

// Merge context from both Build VAPI System Prompt and Upsert CRM Lead
const promptData = $('Build VAPI System Prompt').first().json;
const crmRow     = $('Upsert CRM Lead').first().json;

if (!crmRow || !crmRow.id) {
  throw new Error('CRM upsert did not return an id — check the ON CONFLICT clause and phone unique index');
}

return [{
  json: {
    ...promptData,
    crmLeadId: crmRow.id
  }
}];

