// VAPI sends events with this structure:
// { message: { type: "end-of-call-report", call: { analysis: { structuredData: {...} }, ... }, artifact: {...} } }
// CRITICAL: structuredData lives at message.call.analysis.structuredData
// message.analysis is often EMPTY {} — do NOT use it as the primary source.

const body = $input.first().json.body || $input.first().json;

// Unwrap VAPI message envelope
const msg  = body.message || body;

// Only process end-of-call-report events, ignore others (status-update, etc.)
const eventType = msg.type || body.type || '';
if (eventType && eventType !== 'end-of-call-report') {
  return [{ json: { skip: true, eventType } }];
}

const call         = msg.call || body.call || {};
const callId       = call.id              || '';
const callStatus   = call.status          || '';
const endedReason  = call.endedReason     || msg.endedReason || body.endedReason || '';
const transcript   = msg.transcript       || call.transcript  || body.transcript || '';
const recordingUrl = msg.recordingUrl     || call.recordingUrl || body.recordingUrl || '';
const artifact     = msg.artifact         || body.artifact    || {};

// Handle startedAt/endedAt/duration robustly across all nested payload styles
const startedAt    = call.startedAt    || msg.startedAt    || body.startedAt    || '';
const endedAt      = call.endedAt      || msg.endedAt      || body.endedAt      || '';
let duration       = call.durationSeconds || msg.durationSeconds || body.durationSeconds || 0;
if (!duration && startedAt && endedAt) {
  duration = Math.round((new Date(endedAt) - new Date(startedAt)) / 1000);
} else {
  duration = Math.round(Number(duration));
}

const cost = call.cost || msg.cost || body.cost || 0;

// ── STRUCTURED DATA EXTRACTION ──────────────────────────────────────────────
// VAPI delivers structured data at: message.call.analysis.structuredData
// message.analysis is often empty {}; artifact.structuredData is a secondary fallback.
// Priority order: call.analysis.structuredData → artifact.structuredData → msg.analysis.structuredData
const callAnalysis       = call.analysis        || {};
const msgAnalysis        = msg.analysis         || {};
const structuredData     =
  (callAnalysis.structuredData   && Object.keys(callAnalysis.structuredData).length   ? callAnalysis.structuredData   :
   artifact.structuredData       && Object.keys(artifact.structuredData).length       ? artifact.structuredData       :
   msgAnalysis.structuredData    && Object.keys(msgAnalysis.structuredData).length    ? msgAnalysis.structuredData    :
   {});

// Also check legacy structuredOutputs (UUID-keyed format from older VAPI versions)
const structuredOutputs =
  call.structuredOutputs || msg.structuredOutputs || body.structuredOutputs ||
  callAnalysis.structuredOutputs || msgAnalysis.structuredOutputs || {};

// Extract from flat structuredData first (new VAPI format)
let extracted = Object.keys(structuredData).length ? structuredData : {};

// If flat structuredData is empty, try UUID-keyed structuredOutputs (legacy format)
if (!extracted || !Object.keys(extracted).length) {
  for (const key in structuredOutputs) {
    if (structuredOutputs[key] && structuredOutputs[key].name === 'call_analysis') {
      extracted = structuredOutputs[key].result || {};
      break;
    }
  }
  if (!extracted || !Object.keys(extracted).length) {
    for (const key in structuredOutputs) {
      if (structuredOutputs[key] && structuredOutputs[key].result) {
        extracted = structuredOutputs[key].result;
        break;
      }
    }
  }
}

// Summary: prefer structured, then VAPI's top-level transcript summary
const summary =
  extracted.summary       ||
  callAnalysis.summary    ||
  msgAnalysis.summary     ||
  msg.summary             ||
  body.summary            || '';

// Pull metadata we stored on call creation
const meta       = call.metadata || body.metadata || {};
const crmLeadId  = meta.crm_lead_id  || '';
const adType     = meta.ad_type      || '';
const entityUuid = meta.entity_uuid  || '';
const retryCount = parseInt(meta.retry_count || '0');

if (!crmLeadId) {
  // Can't update CRM without a lead ID — log and skip
  return [{ json: { skip: true, reason: 'no crm_lead_id in metadata', callId } }];
}

// ── OUTCOME DETERMINATION ───────────────────────────────────────────────────
// Primary: structured field; Fallback: keyword scan of summary + transcript
let outcome = (extracted.outcome || '').toUpperCase().trim();

const VALID_OUTCOMES = ['QUALIFIED', 'NOT_INTERESTED', 'NO_BUDGET_MATCH', 'CALLBACK_NEEDED', 'NO_ANSWER'];
if (!VALID_OUTCOMES.includes(outcome)) {
  outcome = 'UNKNOWN';
}

if (outcome === 'UNKNOWN') {
  const haystack = (summary + ' ' + transcript + ' ' + endedReason).toUpperCase();
  const noAnswerReasons = [
    'customer-did-not-answer', 'no-answer', 'voicemail',
    'machine-detected', 'machine_end_other', 'silence-timed-out'
  ];
  if (noAnswerReasons.some(r => endedReason.toLowerCase().includes(r))) {
    outcome = 'NO_ANSWER';
  } else if (haystack.includes('CONFIRM THAT YOU ARE QUALIFIED') || haystack.includes('OUTCOME: QUALIFIED')) {
    outcome = 'QUALIFIED';
  } else if (haystack.includes('NOTE THAT YOU ARE NOT INTERESTED') || haystack.includes('OUTCOME: NOT_INTERESTED')) {
    outcome = 'NOT_INTERESTED';
  } else if (haystack.includes('NO BUDGET MATCH') || haystack.includes('OUTCOME: NO_BUDGET_MATCH')) {
    outcome = 'NO_BUDGET_MATCH';
  } else if (haystack.includes('CALLBACK IS NEEDED') || haystack.includes('OUTCOME: CALLBACK_NEEDED')) {
    outcome = 'CALLBACK_NEEDED';
  } else if (callStatus === 'ended' || callStatus === 'completed') {
    outcome = 'COMPLETED_UNKNOWN';
  }
}

// Budget: structured field first, then regex scan of transcript
let mentionedBudget = extracted.mentionedBudget || extracted.budget || null;
if (!mentionedBudget) {
  const budgetMatch = transcript.match(/(SAR\s*)?([\d,\.]+)\s*(million|M|K|SAR)/i);
  mentionedBudget = budgetMatch ? budgetMatch[0].trim() : null;
}

// Additional structured qualification fields
const cityPreference     = extracted.cityPreference     || extracted.city_preference     || '';
const deliveryPreference = extracted.deliveryPreference || extracted.delivery_preference || '';
const purchasePurpose    = extracted.purchasePurpose    || extracted.purchase_purpose    || '';
const timeline           = extracted.timeline           || '';

// Truncate transcript/summary to avoid DB overflow
const transcriptShort = String(transcript).substring(0, 3000);
const summaryShort    = String(summary).substring(0, 1000);

return [{
  json: {
    skip: false,
    callId, callStatus, endedReason,
    transcript: transcriptShort,
    summary: summaryShort,
    recordingUrl, duration, cost,
    crmLeadId, adType, entityUuid, retryCount,
    outcome, mentionedBudget,
    cityPreference, deliveryPreference, purchasePurpose, timeline
  }
}];

const data  = $input.first().json;
const retry = data.retryCount || 0;

if (retry < 2) {
  const delayHours = retry === 0 ? 2 : 24;
  return [{
    json: {
      ...data,
      action:         'RETRY',
      nextRetryCount: retry + 1,
      delayHours,
      scheduledAt: new Date(Date.now() + delayHours * 3_600_000).toISOString()
    }
  }];
}
return [{
  json: {
    ...data,
    action: 'COLD',
    reason: 'No answer after 3 VAPI call attempts'
  }
}];
